def transform(wb):
    ws = wb['Sheet1']
    data = []
    for r in range(2, 9):
        idv = ws.cell(row=r, column=1).value
        name = ws.cell(row=r, column=2).value
        dt = ws.cell(row=r, column=3).value
        amt = ws.cell(row=r, column=4).value
        if amt is None:
            amt = 0
        else:
            amt = int(amt)
        data.append([idv, name, dt, amt])
    unique = []
    for item in data:
        found = False
        for u in unique:
            if u[0] == item[0]:
                u[3] = u[3] + item[3]
                found = True
                break
        if not found:
            unique.append([item[0], item[1], item[2], item[3]])
    for i in range(7):
        r = 2 + i
        if i < len(unique):
            row = unique[i]
            ws.cell(row=r, column=1).value = row[0]
            ws.cell(row=r, column=2).value = row[1]
            c = ws.cell(row=r, column=3)
            c.value = row[2]
            c.number_format = 'm/dd/yyyy hh:ss'
            d = ws.cell(row=r, column=4)
            d.value = row[3]
            d.number_format = '#,##0'
        else:
            for col in range(1, 5):
                cell = ws.cell(row=r, column=col)
                cell.value = None
                if col == 3:
                    cell.number_format = 'm/dd/yyyy hh:ss'
                elif col == 4:
                    cell.number_format = '#,##0'
    for r in range(2, 9):
        for col in range(1, 5):
            cell = ws.cell(row=r, column=col)
            f = copy(cell.font)
            f.bold = False
            f.color = 'FF000000'
            cell.font = f
    return None
